const cedis = n => '₵'+money(n);
const cleanNumericDisplay = value => { if(value===null||value===undefined||value==='') return value??''; const n=Number(value); return Number.isFinite(n)?String(n):String(value).replace(/(\.\d*?)0+$/,'$1').replace(/\.$/,''); };
const escapeHtml = value => String(value??'').replace(/[&<>\"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[ch]));
