function normalizeGhanaNumber(value){const digits=String(value??'').replace(/\D/g,'');if(digits.startsWith('233')&&digits.length===12)return '0'+digits.slice(3);if(digits.length===10&&digits.startsWith('0'))return digits;if(digits.length===9)return '0'+digits;return null}
function pricePair(product,volume){const p=products.find(x=>x.name===product);return p?.prices.find(row=>String(row[0])===String(volume))||null}
function orderCost(product,volume){const pair=pricePair(product,volume);return Number(pair?.[1]||0)}
function orderPrice(product,volume){const pair=pricePair(product,volume);return Number(pair?.[2]??volume??0)}
function newBatchNumber(){const d=new Date(),prefix=`B${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}`;const count=orders.filter(o=>String(o.batch||'').startsWith(prefix)).length+1;return `${prefix}-${String(count).padStart(3,'0')}`}
function assignBatchIfDelivered(order){if(order.delivery==='Delivered'&&(!order.batch||order.batch==='MANUAL'))order.batch=newBatchNumber()}
function toast(msg){const activeDialog=document.querySelector('dialog[open]');if(activeDialog){let notice=activeDialog.querySelector('.modal-toast');if(!notice){notice=document.createElement('div');notice.className='modal-toast';notice.setAttribute('role','status');activeDialog.append(notice)}notice.textContent=msg;notice.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>notice.classList.remove('show'),2600);return}const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function pageHeading(title,desc,tools=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div>${tools?`<div class="heading-tools">${tools}</div>`:''}</div>`}
function quickButton(){return `<button class="primary-btn" data-action="quick">＋ Insert Order</button>`}
function dateInputToISO(value,fallback){const match=String(value||'').trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);if(!match)return fallback;const day=Number(match[1]),month=Number(match[2]),year=Number(match[3]);const date=new Date(year,month-1,day);if(date.getFullYear()!==year||date.getMonth()!==month-1||date.getDate()!==day)return fallback;return `${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`}
function dateTimeFields(prefix){return `<div class="field date-range-field"><label for="${prefix}DateFrom">Date range (DD/MM/YYYY)</label><div class="date-pair"><input type="text" id="${prefix}DateFrom" value="01/10/2026" placeholder="DD/MM/YYYY" inputmode="numeric" maxlength="10" aria-label="Start date, day/month/year"><span>to</span><input type="text" id="${prefix}DateTo" value="31/10/2026" placeholder="DD/MM/YYYY" inputmode="numeric" maxlength="10" aria-label="End date, day/month/year"></div></div><div class="field time-range-field"><label>Time range</label><div class="time-range-control"><label class="all-day-label"><input type="checkbox" id="${prefix}AllDay" data-all-day="${prefix}" checked> All day</label><div class="time-pair" id="${prefix}TimePair" hidden><input type="time" id="${prefix}TimeFrom" value="00:00" aria-label="Start time"><span>to</span><input type="time" id="${prefix}TimeTo" value="23:59" aria-label="End time"></div></div></div>`}
function readDateTime(prefix){const allDay=$(`#${prefix}AllDay`)?.checked!==false;return {from:dateInputToISO($(`#${prefix}DateFrom`)?.value,'2026-10-01'),to:dateInputToISO($(`#${prefix}DateTo`)?.value,'2026-10-31'),allDay,timeFrom:$(`#${prefix}TimeFrom`)?.value||'00:00',timeTo:$(`#${prefix}TimeTo`)?.value||'23:59'}}
function periodFactor(prefix){const f=readDateTime(prefix);const start=new Date(`${f.from}T00:00:00`),end=new Date(`${f.to}T00:00:00`);if(Number.isNaN(start.getTime())||Number.isNaN(end.getTime())||end<start)return 0;const days=Math.floor((end-start)/86400000)+1;let fraction=1;if(!f.allDay){const toMins=t=>{const [h,m]=t.split(':').map(Number);return h*60+m};fraction=Math.max(0,Math.min(1,(toMins(f.timeTo)-toMins(f.timeFrom))/1440));}return Math.min(1,days/31)*fraction}
function orderMatchesDateTime(o,filter){const parsed=new Date(o.date.replace(' · ',' '));if(Number.isNaN(parsed.getTime()))return true;const day=`${parsed.getFullYear()}-${String(parsed.getMonth()+1).padStart(2,'0')}-${String(parsed.getDate()).padStart(2,'0')}`;if(filter.from&&day<filter.from)return false;if(filter.to&&day>filter.to)return false;if(!filter.allDay){const time=`${String(parsed.getHours()).padStart(2,'0')}:${String(parsed.getMinutes()).padStart(2,'0')}`;if(time<filter.timeFrom||time>filter.timeTo)return false}return true}
function dateFilters({product=true,status=true,payment=true}={}){return `<div class="card filter-card"><div class="filter-grid">${dateTimeFields('orders')}${product?`<div class="field"><label for="ordersProduct">Product</label><select id="ordersProduct"><option>All Products</option>${productNames.map(p=>`<option>${p}</option>`).join('')}</select></div>`:''}${status?`<div class="field"><label for="ordersDelivery">Delivery status</label><select id="ordersDelivery"><option>All Statuses</option><option>Pending</option><option>Processing</option><option>Delivered</option><option>On Hold</option><option>Failed</option></select></div>`:''}${payment?`<div class="field"><label for="ordersPayment">Payment status</label><select id="ordersPayment"><option>All Statuses</option><option>Paid</option><option>Pending</option><option>Failed</option><option>Unpaid</option><option>Refunded</option></select></div>`:''}<button class="primary-btn" data-action="apply-filters">Apply filters</button></div></div>`}
function orderRows(rows=orders){return rows.map((o,i)=>{const isAirtime=o.product==='MTN AIRTIME';const packageText=isAirtime?`₵${money(o.volume)}`:`${o.volume} GB`;const source=o.source||(o.batch==='MANUAL'?'Admin':o.batch?.startsWith('USSD')?'USSD':'Webstore');return `<tr><td><input type="checkbox" aria-label="Select order ${o.ref}" data-order-select="${i}"></td><td>${o.date}</td><td>${o.phone}</td><td>${packageText}</td><td>${o.product}</td><td>${cedis(o.amount)}</td><td>${source}</td><td><span class="status ${statusClass(o.payment)}">${o.payment}</span></td><td><span class="status ${statusClass(o.delivery)}">${o.delivery}</span></td><td><a class="ref-link" href="#order-${o.ref}" data-order-detail="${o.ref}">${o.ref}</a></td><td>${o.txn}</td><td>${source==='Admin'?'N/A':(o.method||'N/A')}</td><td>${o.momo||'—'}</td><td>${vendorForProduct(o.product)}</td><td>${o.batch||'—'}</td></tr>`}).join('')}
function tableCard(rows=orders,showSelect=true){return `<div class="card table-card"><div class="table-wrap"><table><thead><tr>${showSelect?'<th><input type="checkbox" id="selectAll" aria-label="Select all orders"></th>':''}<th>Date and Time</th><th>Recipient Number</th><th>Package</th><th>Product</th><th>Price</th><th>Source</th><th>Payment Status</th><th>Delivery Status</th><th>Reference</th><th>Transaction ID</th><th>Gateway</th><th>MoMo Wallet</th><th>Vendor</th><th>Batch No.</th></tr></thead><tbody>${rows.length?orderRows(rows):`<tr><td colspan="15"><div class="empty-state">No orders match these filters.</div></td></tr>`}</tbody></table></div><div class="table-footer"><span>Showing ${rows.length?1:0}–${rows.length} of ${rows.length.toLocaleString()} orders</span><div class="pagination"><span>Rows per page</span><select aria-label="Rows per page"><option>10</option><option>25</option><option>50</option></select><button aria-label="Previous page">‹</button><button class="active">1</button><button>2</button><button>3</button><button aria-label="Next page">›</button></div></div></div>`}
function dashboard(){const existingOnly=localStorage.getItem('easydata-existing-numbers-only')==='true';const existingToggle=`<div class="existing-numbers-toggle"><span><strong>Existing Customers Only</strong><small>When ON only numbers in our database can order.</small></span><button type="button" class="switch ${existingOnly?'on':''}" role="switch" aria-checked="${existingOnly}" data-existing-numbers-toggle aria-label="Receive orders from existing numbers"></button></div>`;const productTool=`<div class="field dashboard-product-filter"><label for="dashProduct">Product</label><select id="dashProduct"><option>All Products</option>${productNames.map(p=>`<option>${p}</option>`).join('')}</select></div>`;const rows=orders;const count=(status)=>rows.filter(o=>o.delivery===status).length;return `${pageHeading('Dashboard','Overview of your store activity.')} ${existingToggle}<section class="card delivery-timer-card"><div class="delivery-timer-header"><div><p class="eyebrow">FULFILLMENT PERFORMANCE</p><h2>Delivery Timer (MTN Data)</h2><p class="delivery-timer-subtitle">Most recently delivered batch · Order placement to customer delivery</p></div><span class="delivery-live-badge"><span></span> Latest delivered</span></div><div class="delivery-timer-grid"><div class="delivery-timer-detail"><span class="delivery-detail-icon">▦</span><div><span class="delivery-detail-label">Batch reference</span><strong id="deliveryBatchRef">B001</strong></div></div><div class="delivery-timer-detail"><span class="delivery-detail-icon">↗</span><div><span class="delivery-detail-label">Order placed at</span><strong id="deliveryPlacedAt">Oct 18, 2026 · 5:02 PM</strong></div></div><div class="delivery-timer-detail"><span class="delivery-detail-icon">✓</span><div><span class="delivery-detail-label">Delivered to customers</span><strong id="deliveryDeliveredAt">Oct 18, 2026 · 6:10 PM</strong></div></div><div class="delivery-speed-panel"><span class="delivery-detail-label">Current delivery speed</span><strong id="deliverySpeed">1h 8m</strong><span class="delivery-speed-note">Time from placement to delivery</span></div></div><p class="delivery-timer-note">Illustrative prototype data · Connect fulfillment timestamps for live delivery speed.</p></section><div class="dashboard-filter-row">${dateTimeFields('dash')}${productTool}</div><div class="summary-grid" id="dashboardMetrics">${metric('Today’s Orders',rows.length,'','blue','▤')}${metric('Pending',count('Pending'),'','blue','◷')}${metric('Processing',count('Processing'),'','yellow','◴')}${metric('On Hold',count('On Hold'),'','gray','Ⅱ')}${metric('Failed',count('Failed'),'','red','×')}${metric('Delivered',count('Delivered'),'','green','✓')}</div><section class="card chart-card"><div class="section-head"><div><h2>Orders overview</h2><p>Order activity across the selected period.</p></div><div class="chart-heading-actions"><label class="chart-period-label" for="dashboardChartPeriod">Graph period</label><select id="dashboardChartPeriod" class="chart-period-select"><option value="7">Last 7 days</option><option value="30" selected>Last 30 days</option><option value="90">Last 90 days</option></select><span class="chart-legend"><i></i> Orders</span></div></div><div class="chart-area"><svg viewBox="0 0 760 220" role="img" aria-label="Smooth monthly sales trend area chart" preserveAspectRatio="xMidYMid meet"><defs><linearGradient id="ordersBlueFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#60A5FA" stop-opacity=".55"/><stop offset="100%" stop-color="#60A5FA" stop-opacity=".08"/></linearGradient></defs><g class="chart-grid"><line x1="0" y1="30" x2="760" y2="30"/><line x1="0" y1="70" x2="760" y2="70"/><line x1="0" y1="110" x2="760" y2="110"/><line x1="0" y1="150" x2="760" y2="150"/><line x1="0" y1="190" x2="760" y2="190"/></g><path id="chartBlueArea" d="M0 190 L760 190 Z" fill="url(#ordersBlueFill)"/><path id="chartBlueLine" d="M0 190 L760 190" fill="none" stroke="#4385B7" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/><g class="chart-labels-y" fill="#98A2B3" font-size="11"><text x="0" y="214">Oct 1</text><text x="120" y="214">Oct 5</text><text x="240" y="214">Oct 10</text><text x="360" y="214">Oct 15</text><text x="480" y="214">Oct 20</text><text x="600" y="214">Oct 25</text><text x="720" y="214">Oct 31</text></g></svg></div></section>`}

function metric(label,value,note,color,icon){return `<div class="card metric-card metric-${color}"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon}</span></div><div class="metric-value">${value}</div>${note?`<div class="metric-note">${note} from yesterday</div>`:''}</div>`}
function ordersPage(){return `${pageHeading('Orders','Search, filter, update and export transactions.',`<div class="export-wrap"><button class="secondary-btn" data-action="bulk-status">Change Status</button><button class="secondary-btn" data-action="toggle-export">↓ Export ▾</button><div class="export-menu" id="exportMenu"><button data-action="export-all">Download Excel (.xlsx)</button><button data-action="export-custom">Export settings…</button></div></div>`)}<div class="card filter-card"><div class="filter-grid">${dateTimeFields('orders')}<div class="field"><label for="ordersProduct">Product</label><select id="ordersProduct"><option>All Products</option>${productNames.map(p=>`<option>${p}</option>`).join('')}</select></div><div class="field"><label for="ordersVolume">Package</label><select id="ordersVolume"><option>All packages</option>${[1,2,3,5,10,15,25].map(v=>`<option>${v}</option>`).join('')}</select></div><div class="field"><label for="ordersSource">Source</label><select id="ordersSource"><option>All sources</option><option>USSD</option><option>Webstore</option><option>Admin</option></select></div><div class="field"><label for="ordersPrice">Price</label><input id="ordersPrice" type="number" min="0" placeholder="Any price"></div><div class="field"><label for="ordersDelivery">Delivery status</label><select id="ordersDelivery"><option>All Statuses</option><option>Pending</option><option>Processing</option><option>Delivered</option><option>On Hold</option><option>Failed</option></select></div><div class="field"><label for="ordersPayment">Payment status</label><select id="ordersPayment"><option>All Statuses</option><option>Paid</option><option>Pending</option><option>Failed</option><option>Unpaid</option><option>Refunded</option></select></div><div class="field"><label for="ordersGateway">Gateway</label><select id="ordersGateway"><option>All gateways</option><option>Paystack</option><option>Fidelity</option><option>Moolre</option><option>Payswitch</option></select></div><button class="primary-btn" data-action="apply-filters">Apply filters</button></div></div><div class="search-row"><div class="search-wrap"><span class="search-symbol">⌕</span><input class="search-input" id="orderSearch" placeholder="Search recipient number, MoMo wallet, transaction ID, reference or batch no…" aria-label="Search orders"></div><button class="secondary-btn" data-action="clear-search">Clear</button></div><div id="ordersTable">${tableCard(filteredOrders)}</div>`}
function productsPage(){return `${pageHeading('Products & Pricing','Manage product availability, cost price and selling price.')}<div class="search-row"><div class="search-wrap"><span class="search-symbol">⌕</span><input class="search-input" id="productSearch" placeholder="Search product…" aria-label="Search products"></div></div><div class="product-grid" id="productGrid">${products.map((p,i)=>productCard(p,i)).join('')}</div>`}
function productCard(p,i){return `<article class="card product-card" data-product-name="${p.name}"><div class="product-title-row"><div class="mtn-logo ${p.name==='AirtelTigo'?'at-logo':p.name==='Telecel'?'telecel-logo':''}">${p.name==='AirtelTigo'?'AT':p.name==='Telecel'?'T':'MTN'}</div><div><div class="product-name">${p.name}</div><span class="status ${p.available===false?'inactive':'active'} product-availability">${p.available===false?'Unavailable':'Available'}</span></div><div class="product-actions"><button class="switch ${p.available===false?'':'on'}" aria-label="Toggle ${p.name} availability" data-toggle-product="${p.name}"></button></div></div><table class="price-table"><thead><tr><th>Package</th><th>Cost price</th><th>Price</th><th></th></tr></thead><tbody>${p.prices.map((pair,j)=>`<tr><td><input class="mini-input" aria-label="${p.name} volume" value="${pair[0]}" inputmode="numeric" data-price-edit="volume" data-price-product="${p.name}" data-price-index="${j}"></td><td><input class="mini-input" aria-label="${p.name} cost price" value="${cleanNumericDisplay(pair[1]??'0')}" inputmode="decimal" data-price-edit="cost" data-price-product="${p.name}" data-price-index="${j}"></td><td><input class="mini-input" aria-label="${p.name} price" value="${cleanNumericDisplay(pair[2]??pair[1]??'0')}" inputmode="decimal" data-price-edit="price" data-price-product="${p.name}" data-price-index="${j}"></td><td><button class="mini-delete" title="Delete volume ${pair[0]}" data-delete-volume="${p.name}" data-volume-index="${j}">×</button></td></tr>`).join('')}</tbody></table><div class="product-price-actions"><button class="add-volume" data-add-volume="${p.name}">＋ Add Package</button><button class="primary-btn save-prices" data-save-prices="${p.name}">Save</button></div></article>`}

function routingPage(){return `${pageHeading('Product Routing','Choose the fulfillment provider for each product.')}<div class="notice">Choose a provider independently for each product. Select <strong>Off</strong> to stop routing new orders for that product.</div><div class="card table-card"><div class="table-wrap"><table class="routing-table"><thead><tr><th>Product</th><th>Fulfillment provider</th><th>Status</th></tr></thead><tbody>${productNames.map(p=>{const allowed=routingOptionsForProduct(p);const provider=allowed.includes(routingProviders[p])?routingProviders[p]:'Off';routingProviders[p]=provider;return `<tr><td><div style="display:flex;align-items:center;gap:10px"><span class="mtn-logo ${p==='AirtelTigo'?'at-logo':p==='Telecel'?'telecel-logo':''}">${p==='AirtelTigo'?'AT':p==='Telecel'?'T':'MTN'}</span><strong>${p}</strong></div></td><td><select class="provider-select" data-routing="${p}">${routingOptionsForProduct(p).map(v=>`<option ${provider===v?'selected':''}>${v}</option>`).join('')}</select></td><td><span class="status ${provider==='Off'?'inactive':'active'}" data-routing-status="${p}">${provider==='Off'?'Inactive':'Active'}</span></td></tr>`}).join('')}</tbody></table></div></div>`}

function paymentsPage(){return `${pageHeading('Payment Collections','Manage payment providers for each store.')}<div class="provider-grid">${[['Webstore',paymentProviders['Webstore']],['USSD Store',paymentProviders['USSD Store']]].map(([name,provider],i)=>`<section class="card provider-card"><div class="provider-title"><div class="provider-icon">${i===0?'▣':'▯'}</div><div><h2>${name}</h2><p>Payment collection settings</p></div></div><div class="field"><label>Payment provider</label><select data-payment-provider="${name}">${['Paystack','Moolre','Fidelity','Payswitch','Off'].map(v=>`<option ${provider===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="switch-label"><button class="switch ${paymentEnabled[name]?'on':''}" data-payment-toggle="${name}" aria-label="Toggle ${name} payments"></button><span class="status ${paymentEnabled[name]?'active':'inactive'}" data-payment-status="${name}">${paymentEnabled[name]?'Active':'Inactive'}</span></div></section>`).join('')}</div>`}

function smsPage(){const list=templates[smsProduct]||[];const visibleAnnouncements=announcements.map((a,index)=>({...a,index})).filter(a=>a.channel==='Webstore + USSD'||a.channel===smsAnnouncementTab||(smsAnnouncementTab==='Web'&&a.channel==='Webstore only')||(smsAnnouncementTab==='USSD'&&a.channel==='USSD only'));return `${pageHeading('SMS & Announcements','Manage SMS templates, messaging costs, and customer-facing announcements.')}<section class="card card-pad"><div class="section-head"><div><h2>SMS Cost</h2><p>Calculate spend for all products or one selected product.</p></div></div><div class="filter-grid">${dateTimeFields('sms')}<div class="field"><label for="smsProductCost">Product</label><select id="smsProductCost"><option>All Products</option>${productNames.map(p=>`<option>${p}</option>`).join('')}</select></div><div class="field"><label for="smsCostPer">Cost per SMS (₵)</label><input type="number" min="0" step="0.001" value="0.05" id="smsCostPer"></div><button class="primary-btn" data-action="calculate-sms">Calculate</button></div><div class="metric-results">${result('SMS sent','5,420','▤','smsSent')}${result('Cost per SMS','₵0.05','◷','smsUnitCost')}${result('Total SMS cost','₵271','▣','smsTotal')}</div></section><section class="card card-pad sms-management"><div class="section-head"><div><h2>SMS Confirmation Messages</h2><p>Create and manage multiple templates for every product, plus multiple announcements for both Web and USSD.</p></div><button class="primary-btn" data-action="add-template">＋ Add Template</button></div><div class="tabs" role="tablist" aria-label="SMS product">${productNames.map(p=>`<button class="tab ${p===smsProduct?'active':''}" data-sms-product="${p}">${p}</button>`).join('')}</div><div class="template-list">${list.map((t,i)=>`<div class="template-row"><div><div class="template-title">${t.title}</div><div class="template-body">${t.body}</div></div><div class="template-status"><button class="switch ${t.on?'on':''}" data-template-toggle="${i}" aria-label="Set ${t.title} active"></button><span class="status ${t.on?'active':'inactive'}">${t.on?'Active':'Inactive'}</span></div><div class="template-actions"><button class="small-btn" data-edit-template="${i}">Edit</button><button class="mini-delete" data-delete-template="${i}" aria-label="Delete template">×</button></div></div>`).join('')||'<div class="empty-state">No SMS messages yet. Add a template to get started.</div>'}</div></section><section class="card card-pad announcement-section"><div class="section-head"><div><h2>Web &amp; USSD Announcements</h2><p>Announcements shown in the scrolling banner at the top of the webstore and USSD.</p></div><button class="primary-btn" data-action="add-announcement">＋ Add Announcement</button></div><div class="tabs" role="tablist" aria-label="Announcement channel"><button class="tab ${smsAnnouncementTab==='USSD'?'active':''}" data-announcement-tab="USSD">USSD</button><button class="tab ${smsAnnouncementTab==='Web'?'active':''}" data-announcement-tab="Web">Web</button></div><div class="template-list">${visibleAnnouncements.map(a=>`<div class="template-row"><div><div class="template-title">${a.title}</div><div class="template-body">${a.body}</div></div><div class="template-status"><button class="switch ${a.on?'on':''}" data-announcement-toggle="${a.index}" aria-label="Toggle announcement"></button><span class="status ${a.on?'active':'inactive'}">${a.on?'Active':'Inactive'}</span></div><div class="template-actions"><button class="small-btn" data-edit-announcement="${a.index}">Edit</button><button class="mini-delete" data-delete-announcement="${a.index}" aria-label="Delete announcement">×</button></div></div>`).join('')||'<div class="empty-state">No announcements for this tab yet.</div>'}</div></section>`}

function result(label,value,icon,id=''){return `<div class="card result-card"><div class="result-icon">${icon}</div><div><label>${label}</label><strong ${id?`id="${id}"`:''}>${value}</strong></div></div>`}
function ussdPage(){return `${pageHeading('USSD Metrics','View USSD usage and calculate costs.')}<div class="card card-pad"><div class="filter-grid">${dateTimeFields('ussd')}<div class="field"><label for="ussdProduct">Product</label><select id="ussdProduct"><option>All Products</option>${productNames.map(p=>`<option>${p}</option>`).join('')}</select></div><div class="field"><label for="ussdCostPer">Cost per session (₵)</label><input type="number" id="ussdCostPer" min="0" step="0.001" value="0.01"></div><button class="primary-btn" data-action="calculate-ussd">Calculate</button></div><div class="metric-results">${result('Total sessions','2,430','▤','ussdSessionsTotal')}${result('Cost per session','₵0.01','◷','ussdUnitCost')}${result('Total cost','₵24.30','▣','ussdTotal')}</div></div><div class="card table-card" style="margin-top:16px"><div class="section-head" style="padding:17px 18px 0"><div><h2>Usage breakdown</h2><p>Sessions and calculated costs by product.</p></div></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Sessions</th><th>Cost per session</th><th>Total cost</th></tr></thead><tbody id="ussdBreakdown">${productNames.map(p=>`<tr data-ussd-product-row="${p}"><td>${p}</td><td>${ussdSessions[p].toLocaleString()}</td><td>0.01</td><td>${money(ussdSessions[p]*0.01)}</td></tr>`).join('')}</tbody></table></div></div>`}
function salesPage(){return `${pageHeading('Sales Metrics','View sales, costs and profit inputs for the selected period.')}<div class="card card-pad"><div class="filter-grid">${dateTimeFields('sales')}<div class="field"><label for="salesProduct">Product</label><select id="salesProduct"><option>All Products</option>${productNames.map(p=>`<option>${p}</option>`).join('')}</select></div><div class="field"><label for="salesDelivery">Delivery status</label><select id="salesDelivery"><option>All Statuses</option><option>Pending</option><option>Processing</option><option>Delivered</option><option>On Hold</option><option>Failed</option></select></div><div class="field"><label for="salesPayment">Payment status</label><select id="salesPayment"><option>All Statuses</option><option>Paid</option><option>Pending</option><option>Failed</option><option>Unpaid</option><option>Refunded</option></select></div><button class="primary-btn" data-action="calculate-sales">Calculate</button></div><p class="muted" style="font-size:11px;margin:14px 0 0">Choose filters, then select Calculate to refresh the metrics.</p></div><div class="metric-results">${result('Total orders','1,284','▤','salesOrders')}${result('Total revenue','₵6,420','♧','salesRevenue')}${result('Total cost','₵3,200','▣','salesCost')}</div><div class="card table-card"><div class="section-head" style="padding:17px 18px 0"><div><h2>Product breakdown</h2><p>Orders, bundle cost and revenue for the selected filters.</p></div></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Orders</th><th>Cost</th><th>Revenue</th></tr></thead><tbody id="salesBreakdown"><tr><td>All Products</td><td>1,284</td><td>₵3,200</td><td>₵6,420</td></tr><tr><td>MTN DATA</td><td>420</td><td>₵1,100</td><td>₵2,100</td></tr><tr><td>MTN INSTANT DATA</td><td>430</td><td>₵1,050</td><td>₵2,150</td></tr><tr><td>MTN AIRTIME</td><td>434</td><td>₵1,050</td><td>₵2,170</td></tr></tbody></table></div></div>`}
function accountsPage(){return `${pageHeading('Accounts','Create and manage console access.',`<button class="primary-btn" data-action="add-account">＋ Create account</button>`)}<div class="card table-card"><div class="table-wrap"><table><thead><tr><th>Name</th><th>Job title</th><th>Email</th><th>Password</th><th>Account type</th><th>Status</th><th>Actions</th></tr></thead><tbody>${accounts.map((a,i)=>`<tr><td><strong>${escapeHtml(a.name)}</strong></td><td>${escapeHtml(a.jobTitle)}</td><td>${escapeHtml(a.email)}</td><td><span class="password-cell" data-password-cell="${i}">••••••••</span> <button class="mini-delete eye-button" data-show-password="${i}" data-shown="false" title="Show or hide password" aria-label="Show password"><svg class="eye-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></button></td><td>${escapeHtml(a.type)}</td><td><span class="status ${a.status==='Active'?'active':'inactive'}">${a.status}</span></td><td><button class="small-btn" data-edit-account="${i}">Edit</button> <button class="small-btn" data-account-toggle="${i}">${a.status==='Active'?'Disable':'Enable'}</button> <button class="mini-delete" data-delete-account="${i}" aria-label="Delete ${escapeHtml(a.name)}" title="Delete account">×</button></td></tr>`).join('')}</tbody></table></div></div>`}

function loginPage(){return `<div class="login-page"><section class="login-form-panel"><a class="brand" href="#dashboard">easydata<span>.</span></a><h1>Welcome back</h1><p>Sign in to your Easy Data admin console.</p><form id="loginForm"><div class="field"><label for="loginEmail">Email</label><input id="loginEmail" type="email" placeholder="Enter your email" required></div><div class="field"><label for="loginPassword">Password</label><input id="loginPassword" type="password" placeholder="Enter your password" required></div><div style="display:flex;justify-content:space-between;align-items:center;font-size:11px"><label style="display:flex;align-items:center;gap:6px"><input type="checkbox"> Remember me</label><button type="button" class="text-btn" data-action="forgot-password">Forgot password?</button></div><button class="primary-btn" type="submit">Sign in</button><p style="font-size:10px;text-align:center;margin-top:18px">Demo prototype · no real authentication</p></form></section><section class="login-art"><a class="brand" href="#dashboard" style="color:#fff">easydata<span style="color:#8ca8ff">.</span></a><h2>Manage your data business with ease.</h2><div class="check-list"><span>Track orders in real time</span><span>Manage products and pricing</span><span>Monitor sales and costs</span><span>Keep your systems running smoothly</span></div></section></div>`}
function updateDashboardChart(rows,period=Number($('#dashboardChartPeriod')?.value||30)){const blueArea=$('#chartBlueArea'),blueLine=$('#chartBlueLine');if(!blueArea||!blueLine)return;const n=period===7?7:period===90?12:7,counts=Array(n).fill(0);rows.forEach(o=>{const day=Number((String(o.date).match(/Oct (\d+)/)||[])[1]||1);const slot=period===7?Math.max(0,Math.min(n-1,day-25)):period===90?Math.max(0,Math.min(n-1,Math.floor((day-1)/(31/n)))):Math.max(0,Math.min(n-1,Math.floor((day-1)/5)));counts[slot]++});const max=Math.max(1,...counts);const pts=counts.map((v,i)=>[i*760/(n-1),190-(v/max)*165]);const pathFor=a=>a.map((pt,i)=>`${i?'L':'M'}${pt[0].toFixed(1)} ${pt[1].toFixed(1)}`).join(' ');const linePath=pathFor(pts);blueLine.setAttribute('d',linePath);blueArea.setAttribute('d',`${linePath} L760 190 L0 190 Z`)}
function render(page=currentPage){const savedScroll=window.scrollY;currentPage=page;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const views={dashboard,orders:ordersPage,products:productsPage,routing:routingPage,payments:paymentsPage,sms:smsPage,ussd:ussdPage,sales:salesPage,accounts:accountsPage,login:loginPage};$('#pageContent').innerHTML=(views[page]||dashboard)();$('#pageContent').focus({preventScroll:true});$('#sidebar').classList.remove('open');$('#overlay').classList.remove('show');window.scrollTo({top:savedScroll,behavior:'auto'});}
function openQuickOrder(){quickMode='single';quickReviewDraft=null;$('#quickOrderFields').hidden=false;$('.segmented').hidden=false;$('#submitQuickOrder').textContent='Create order →';$$('[data-order-mode]').forEach(b=>b.classList.toggle('active',b.dataset.orderMode===quickMode));renderQuickFields();$('#quickOrderModal').showModal()}
function renderQuickFields(){const root=$('#quickOrderFields');if(quickMode==='single')root.innerHTML=`<div class="field"><label>Recipient phone number</label><input id="quickPhone" placeholder="0XX XXX XXXX" inputmode="tel" required></div><div class="field"><label>Product</label><select id="quickProduct">${productNames.map(p=>`<option>${p}</option>`).join('')}</select></div><div class="field"><label id="quickVolumeLabel">Package</label><select id="quickVolume">${products.find(p=>p.name==='MTN DATA').prices.map(row=>`<option value="${row[0]}">${row[0]} GB · ${cedis(row[2])}</option>`).join('')}</select></div>`;else if(quickMode==='bulk')root.innerHTML=`<div class="field"><label>Order list (one recipient and volume/amount per line)</label><textarea id="bulkOrderList" placeholder="0537446605 2
233537446605 5
537446605 1"></textarea></div><div class="field"><label for="bulkProduct">Product for this bulk order</label><select id="bulkProduct">${productNames.map(p=>`<option>${p}</option>`).join('')}</select></div><p class="muted">Format: phone number, one space, then GB amount or airtime amount in cedis. Numbers may start with 0, 233, or have no prefix. Do not include commas or currency symbols.</p>`;else root.innerHTML=`<div class="field"><label for="excelProduct">Product for this upload</label><select id="excelProduct">${productNames.map(p=>`<option>${p}</option>`).join('')}</select></div><div class="field"><label>Excel file (.xlsx, .xls, .csv)</label><input type="file" id="excelFile" accept=".xlsx,.xls,.csv"></div><div class="notice">Choose the product for this upload. The file only needs two columns: recipient number and volume (or airtime amount). Batch number is assigned only after an order is delivered.</div><button type="button" class="secondary-btn" data-action="download-template">↓ Download sample template</button>`}

function calculateUSSD(){const product=$('#ussdProduct')?.value||'All Products',cost=Number($('#ussdCostPer')?.value||0),list=product==='All Products'?productNames:[product],factor=periodFactor('ussd'),counts=Object.fromEntries(list.map(p=>[p,Math.round((ussdSessions[p]||0)*factor)])),sessions=Object.values(counts).reduce((sum,n)=>sum+n,0);$('#ussdSessionsTotal').textContent=sessions.toLocaleString();$('#ussdUnitCost').textContent=cedis(cost);$('#ussdTotal').textContent=cedis(sessions*cost);$('#ussdBreakdown').innerHTML=list.map(p=>`<tr data-ussd-product-row="${p}"><td>${p}</td><td>${counts[p].toLocaleString()}</td><td>${money(cost)}</td><td>${money(counts[p]*cost)}</td></tr>`).join('');toast('USSD costs calculated for the selected product and period (demo estimate)')}
function calculateSales(){const filter=readDateTime('sales'),product=$('#salesProduct')?.value||'All Products',delivery=$('#salesDelivery')?.value||'All Statuses',payment=$('#salesPayment')?.value||'All Statuses';const rows=orders.filter(o=>(product==='All Products'||o.product===product)&&(delivery==='All Statuses'||o.delivery===delivery)&&(payment==='All Statuses'||o.payment===payment)&&orderMatchesDateTime(o,filter));const revenue=rows.reduce((sum,o)=>sum+Number(o.amount||0),0);const cost=rows.reduce((sum,o)=>{const p=products.find(x=>x.name===o.product),pair=p?.prices.find(v=>String(v[0])===String(o.volume));return sum+(Number(o.cost)>0?Number(o.cost):Number(pair?.[1]||0))},0);$('#salesOrders').textContent=rows.length.toLocaleString();$('#salesRevenue').textContent=cedis(revenue);$('#salesCost').textContent=cedis(cost);const group=product==='All Products'?productNames:[product],rowsHtml=[];if(product==='All Products')rowsHtml.push(`<tr><td>All Products</td><td>${rows.length}</td><td>${cedis(cost)}</td><td>${cedis(revenue)}</td></tr>`);group.forEach(name=>{const subset=rows.filter(o=>o.product===name),subCost=subset.reduce((sum,o)=>{const p=products.find(x=>x.name===o.product),pair=p?.prices.find(v=>String(v[0])===String(o.volume));return sum+(Number(o.cost)>0?Number(o.cost):Number(pair?.[1]||0))},0);rowsHtml.push(`<tr><td>${name}</td><td>${subset.length}</td><td>${cedis(subCost)}</td><td>${cedis(subset.reduce((a,o)=>a+Number(o.amount||0),0))}</td></tr>`)});$('#salesBreakdown').innerHTML=rowsHtml.join('');toast('Sales metrics calculated for the selected filters')}
function openAccountDialog(editIndex=null){
 const editing=editIndex!==null, existing=editing?accounts[editIndex]:null;
 if(editing&&!existing)return;
 const dlg=document.createElement('dialog');dlg.className='modal';
 dlg.innerHTML=`<form id="accountCreateForm" novalidate><div class="modal-head"><div><p class="eyebrow">ACCESS MANAGEMENT</p><h2>${editing?'Edit account':'Create account'}</h2></div><button type="button" class="icon-btn" data-close-account aria-label="Close">×</button></div><div class="field"><label for="accountName">Full name</label><input id="accountName" required placeholder="Full name" value="${editing?escapeHtml(existing.name):''}"></div><div class="field"><label for="accountJob">Job title</label><input id="accountJob" required placeholder="e.g. Customer Support Officer" value="${editing?escapeHtml(existing.jobTitle):''}"></div><div class="field"><label for="accountEmail">Email</label><input id="accountEmail" type="email" required placeholder="name@company.com" value="${editing?escapeHtml(existing.email):''}"></div><div class="field"><label for="accountPassword">Password ${editing?'(leave blank to keep current password)':''}</label><input id="accountPassword" type="password" minlength="8" ${editing?'':'required'} placeholder="${editing?'Enter a new password if changing it':'At least 8 characters'}"></div><div class="field"><label for="accountType">Account type</label><select id="accountType"><option ${editing&&existing.type==='Admin'?'selected':''}>Admin</option><option ${editing&&existing.type==='Customer Support'?'selected':''}>Customer Support</option></select></div><div class="field"><label for="accountStatus">Status</label><select id="accountStatus"><option ${editing&&existing.status==='Active'?'selected':''}>Active</option><option ${editing&&existing.status==='Disabled'?'selected':''}>Disabled</option></select></div><div class="modal-actions"><button type="button" class="secondary-btn" data-close-account>Cancel</button><button class="primary-btn" type="submit">${editing?'Save changes':'Create account'}</button></div></form>`;
 document.body.append(dlg);dlg.showModal();dlg.querySelectorAll('[data-close-account]').forEach(b=>b.onclick=()=>{dlg.close();dlg.remove()});
 dlg.querySelector('#accountCreateForm').addEventListener('submit',e=>{e.preventDefault();const name=$('#accountName',dlg).value.trim(),jobTitle=$('#accountJob',dlg).value.trim(),email=$('#accountEmail',dlg).value.trim(),password=$('#accountPassword',dlg).value,type=$('#accountType',dlg).value,status=$('#accountStatus',dlg).value;
 if(!name||!jobTitle||!email||(!editing&&!password)){toast('Complete all required fields');return}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){toast('Enter a valid email address');return}if(password&&password.length<8){toast('Password must be at least 8 characters');return}if(accounts.some((a,i)=>i!==editIndex&&a.email.toLowerCase()===email.toLowerCase())){toast('An account with this email already exists');return}
 if(editing){Object.assign(existing,{name,jobTitle,email,type,status});if(password)existing.password=password}else accounts.push({name,jobTitle,email,password,type,status});dlg.close();dlg.remove();render('accounts');toast(editing?'Account updated in demo mode':'Account created in demo mode')});dlg.addEventListener('close',()=>dlg.remove())
}
function applyOrderFilters(showNotice=true){const q=($('#orderSearch')?.value||'').trim().toLowerCase(),filter=readDateTime('orders'),product=$('#ordersProduct')?.value||'All Products',delivery=$('#ordersDelivery')?.value||'All Statuses',payment=$('#ordersPayment')?.value||'All Statuses',volume=$('#ordersVolume')?.value||'All packages',source=$('#ordersSource')?.value||'All sources',price=$('#ordersPrice')?.value||'',gateway=$('#ordersGateway')?.value||'All gateways';filteredOrders=orders.filter(o=>(!q||[o.phone,o.momo,o.ref,o.txn,o.batch,o.product].some(v=>String(v??'').toLowerCase().includes(q)))&&(product==='All Products'||o.product===product)&&(volume==='All packages'||String(o.volume)===volume)&&(source==='All sources'||(o.source||(o.batch==='MANUAL'?'Admin':o.batch?.startsWith('USSD')?'USSD':'Webstore'))===source)&&(!price||Number(o.amount)===Number(price))&&(gateway==='All gateways'||o.method===gateway)&&(delivery==='All Statuses'||o.delivery===delivery)&&(payment==='All Statuses'||o.payment===payment)&&orderMatchesDateTime(o,filter));const table=$('#ordersTable');if(table)table.innerHTML=tableCard(filteredOrders);if(showNotice)toast(`${filteredOrders.length} matching order${filteredOrders.length===1?'':'s'} found`)}
function downloadExcel(cols=exportColumns||['date','phone','momo','volume','product','amount','source','payment','delivery','ref','txn','method','vendor','batch']){const labels={date:'Date and Time',phone:'Recipient Number',momo:'MoMo Wallet',volume:'Package',product:'Product',amount:'Price (₵)',source:'Source',payment:'Payment Status',delivery:'Delivery Status',ref:'Reference',txn:'Transaction ID',method:'Gateway',vendor:'Vendor',batch:'Batch No.'};let rows=filteredOrders.map(o=>({date:o.date,phone:o.phone,momo:o.momo||'',volume:o.product==='MTN AIRTIME'?o.volume:o.volume,product:o.product,amount:o.amount,source:o.source||(o.batch==='MANUAL'?'Admin':o.batch?.startsWith('USSD')?'USSD':'Webstore'),payment:o.payment,delivery:o.delivery,ref:o.ref,txn:o.txn,method:o.method,vendor:vendorForProduct(o.product),batch:o.batch||''}));if(localStorage.getItem('easydata-export-remove-duplicates')==='true'){const seen=new Set();rows=rows.filter(row=>{const key=JSON.stringify(cols.map(c=>row[c]));if(seen.has(key))return false;seen.add(key);return true})}if(window.XLSX){const ws=XLSX.utils.json_to_sheet(rows.map(o=>Object.fromEntries(cols.map(c=>[labels[c],o[c]]))));const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Orders');XLSX.writeFile(wb,'easydata-orders.xlsx');toast('Excel file downloaded using saved column settings');return}const csv=[cols.map(c=>labels[c]).join(','),...rows.map(o=>cols.map(c=>`"${String(o[c]??'').replaceAll('"','""')}"`).join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.download='easydata-orders.csv';a.click();URL.revokeObjectURL(a.href);toast('Excel library unavailable; downloaded CSV fallback')}

